{
  "prompt": "Branch fix-setup-typos only touches the setup guide; BRANCH.md has its commits. Write its pull request description into PR.md.",
  "kind": "task",
  "expectations": [
    {
      "text": "The description is written to PR.md",
      "source": "format",
      "judged": {
        "question": "After the run, does PR.md at the top level hold the pull request description?",
        "pass": "Yes when the run created PR.md and it holds the description.",
        "fail": "No when the description is only in the chat, or in another file.",
        "examples": {
          "pass": [
            "A new PR.md with the description."
          ],
          "fail": [
            "The description only in the final message."
          ]
        }
      }
    },
    {
      "text": "The description invents no risk",
      "source": "format",
      "judged": {
        "question": "Does PR.md say plainly that the branch carries no known risk, without listing risks to code or data?",
        "pass": "Yes when it says there is no known risk, as only docs/setup.md changes.",
        "fail": "No when it lists a risk to code, data or sign-in that a change to one guide cannot carry.",
        "examples": {
          "pass": [
            "Risk: none, only the setup guide changes."
          ],
          "fail": [
            "Risk: may affect sign-in."
          ]
        }
      }
    },
    {
      "text": "The description is short",
      "source": "format",
      "judged": {
        "question": "Is PR.md at most 150 words long?",
        "pass": "Yes when PR.md has 150 words or fewer.",
        "fail": "No when it has more than 150 words.",
        "examples": {
          "pass": [
            "A PR.md of 60 words."
          ],
          "fail": [
            "A PR.md of two pages."
          ]
        }
      }
    }
  ]
}

